2	import type { Feature } from '../../router/routes';
3	import { useJsonResource } from '../../ui/useJsonResource';
4	
5	// Projects feature: add a project and pick which client it is for, then list every project showing
6	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
7	// against it, their running total, and a form to add another. Owns its own state; talks to its own
8	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
9	// data-testid anchors follow the spec's conventions.
10	type Client = { id: number; name: string; email: string };
11	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
12	type Project = {
13	  id: number;
14	  name: string;
15	  code: string;
16	  clientId: number;
17	  clientName: string;
18	  archived: boolean;
19	  status: ProjectStatus;
20	};
21	type Invoice = {
22	  id: number;
23	  projectId: number;
24	  amount: number;
25	  amountDue: number;
26	  status: string;
27	  issuedDate: string;
28	  dueDate: string;
29	  discountPct: number;
30	  taxPct: number;
31	};
32	type Task = { id: number; projectId: number; title: string; done: boolean };
33	type Tag = { id: number; name: string };
34	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
35	
36	type LineItem = {
37	  id: number;
38	  invoiceId: number;
39	  description: string;
40	  qty: number;
41	  unit: string;
42	  unitPrice: number;
43	};
44	
45	type Payment = { id: number; invoiceId: number; amount: number; date: string };
46	
47	function money(amount: number): string {
48	  return `$${Number(amount).toLocaleString('en-US', {
49	    minimumFractionDigits: 2,
50	    maximumFractionDigits: 2,
51	  })}`;
52	}
53	
54	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
55	// readable at a glance.
56	function moneyGrouped(amount: number): string {
57	  return `$${Number(amount).toLocaleString('en-US', {
58	    minimumFractionDigits: 2,
59	    maximumFractionDigits: 2,
60	  })}`;
61	}
62	
63	type ProjectBudget = { budget: number | null; invoiced: number; remaining: number | null };
64	
65	// One charge line while it is being edited on screen: the fields are held as raw strings so the
66	// inputs stay controlled and the total can recompute live as they change.
67	type EditItem = { id: number; description: string; qty: string; unit: string; unitPrice: string };
68	
69	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
70	// many, price each), the total worked out for you, and a form to add another line. Each line can be
71	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
72	// own line-item state, scoped to the one invoice it is showing.
73	function InvoiceDetail({
74	  invoiceId,
75	  onChange,
76	  onClose,
77	}: {
78	  invoiceId: number;
79	  onChange: () => void;
80	  onClose: () => void;
81	}) {
82	  const [items, setItems] = useState<EditItem[]>([]);
83	  const [description, setDescription] = useState('');
84	  const [qty, setQty] = useState('');
85	  const [unit, setUnit] = useState('');
86	  const [unitPrice, setUnitPrice] = useState('');
87	  const [payments, setPayments] = useState<Payment[]>([]);
88	  const [paymentAmount, setPaymentAmount] = useState('');
89	  const [paymentDate, setPaymentDate] = useState('');
90	  const [status, setStatus] = useState('');
91	  // The percentage discount taken off this invoice's subtotal (0 unless one is set).
92	  const [discountPct, setDiscountPct] = useState(0);
93	  // The percentage sales tax added on top after the discount (0 unless one is set).
94	  const [taxPct, setTaxPct] = useState(0);
95	
96	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
97	  // a payment is added rather than flipping it by hand. The discount and tax percentages come back
98	  // on the same read.
99	  async function loadStatus() {
100	    const res = await fetch(`/api/invoices/${invoiceId}`);
101	    const inv: Invoice = await res.json();
102	    setStatus(inv.status);
103	    setDiscountPct(Number(inv.discountPct) || 0);
104	    setTaxPct(Number(inv.taxPct) || 0);
105	  }
106	
107	  async function load() {
108	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
109	    const rows: LineItem[] = await res.json();
110	    setItems(
111	      rows.map((li) => ({
112	        id: li.id,
113	        description: li.description,
114	        qty: String(li.qty),
115	        unit: li.unit,
116	        unitPrice: String(li.unitPrice),
117	      })),
118	    );
119	  }
120	
121	  async function loadPayments() {
122	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
123	    setPayments(await res.json());
124	  }
125	
126	  async function submitPayment(e: React.FormEvent) {
127	    e.preventDefault();
128	    const value = Number(paymentAmount);
129	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
130	      return;
131	    }
132	    if (paymentDate.trim() === '') {
133	      return;
134	    }
135	    await fetch(`/api/invoices/${invoiceId}/payments`, {
136	      method: 'POST',
137	      headers: { 'Content-Type': 'application/json' },
138	      body: JSON.stringify({ amount: value, date: paymentDate }),
139	    });
140	    setPaymentAmount('');
141	    setPaymentDate('');
142	    await loadPayments();
143	    await loadStatus();
144	    onChange();
145	  }
146	
147	  useEffect(() => {
148	    void load();
149	    void loadPayments();
150	    void loadStatus();
151	  }, [invoiceId]);
152	
153	  function editField(
154	    id: number,
155	    field: 'description' | 'qty' | 'unit' | 'unitPrice',
156	    value: string,
157	  ) {
158	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
159	  }
160	
161	  function amountOf(li: EditItem): number {
162	    const line = Number(li.qty) * Number(li.unitPrice);
163	    return Number.isFinite(line) ? line : 0;
164	  }
165	
166	  async function save(li: EditItem) {
167	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
168	      return;
169	    }
170	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
171	      method: 'POST',
172	      headers: { 'Content-Type': 'application/json' },
173	      body: JSON.stringify({
174	        description: li.description,
175	        qty: Number(li.qty),
176	        unit: li.unit,
177	        unitPrice: Number(li.unitPrice),
178	      }),
179	    });
180	    await load();
181	    onChange();
182	  }
183	
184	  async function remove(id: number) {
185	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
186	    await load();
187	    onChange();
188	  }
189	
190	  async function submit(e: React.FormEvent) {
191	    e.preventDefault();
192	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
193	      return;
194	    }
195	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
196	      method: 'POST',
197	      headers: { 'Content-Type': 'application/json' },
198	      body: JSON.stringify({
199	        description,
200	        qty: Number(qty),
201	        unit,
202	        unitPrice: Number(unitPrice),
203	      }),
204	    });
205	    setDescription('');
206	    setQty('');
207	    setUnit('');
208	    setUnitPrice('');
209	    await load();
210	    onChange();
211	  }
212	
213	  // The subtotal is the sum of the line items; the discount is that percentage taken off it. Sales
214	  // tax is then added on top of the discounted base (worked out after the discount), and the final
215	  // total is the subtotal less the discount plus that tax.
216	  const subtotal = items.reduce((sum, li) => sum + amountOf(li), 0);
217	  const discount = (subtotal * discountPct) / 100;
218	  const tax = ((subtotal - discount) * taxPct) / 100;
219	  const total = subtotal - discount + tax;
220	
221	  return (
222	    <section data-testid="invoice-detail">
223	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
224	        Back to invoices
225	      </button>
226	
227	      <p data-testid="invoice-status">{status}</p>
228	
229	      <table data-testid="invoice-lineitems-table">
230	        <tbody>
231	          {items.map((li) => (
232	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
233	              <td>
234	                <input
235	                  data-testid="lineitem-description"
236	                  value={li.description}
237	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
238	                />
239	              </td>
240	              <td data-testid="lineitem-qty">{li.qty}</td>
241	              <td data-testid="lineitem-unit">{li.unit}</td>
242	              <td>
243	                <input
244	                  data-testid="lineitem-unitprice"
245	                  value={li.unitPrice}
246	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
247	                />
248	              </td>
249	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
250	              <td>
251	                <button
252	                  data-testid={`lineitem-save-${li.id}`}
253	                  type="button"
254	                  onClick={() => save(li)}
255	                >
256	                  Save
257	                </button>
258	                <button
259	                  data-testid={`lineitem-remove-${li.id}`}
260	                  type="button"
261	                  onClick={() => remove(li.id)}
262	                >
263	                  Remove
264	                </button>
265	              </td>
266	            </tr>
267	          ))}
268	        </tbody>
269	      </table>
270	
271	      <p data-testid="invoice-subtotal">{money(subtotal)}</p>
272	      <p data-testid="invoice-discount">{money(discount)}</p>
273	      <p data-testid="invoice-tax">{money(tax)}</p>
274	      <p data-testid="invoice-amount">{money(total)}</p>
275	
276	      <form data-testid="lineitem-form" onSubmit={submit}>
277	        <input
278	          data-testid="lineitem-form-description"
279	          placeholder="Description"
280	          value={description}
281	          onChange={(e) => setDescription(e.target.value)}
282	        />
283	        <input
284	          data-testid="lineitem-form-qty"
285	          placeholder="How many"
286	          value={qty}
287	          onChange={(e) => setQty(e.target.value)}
288	        />
289	        <input
290	          data-testid="lineitem-form-unit"
291	          placeholder="Unit"
292	          value={unit}
293	          onChange={(e) => setUnit(e.target.value)}
294	        />
295	        <input
296	          data-testid="lineitem-form-unitprice"
297	          placeholder="Price each"
298	          value={unitPrice}
299	          onChange={(e) => setUnitPrice(e.target.value)}
300	        />
301	        <button data-testid="lineitem-form-submit" type="submit">
302	          Add line item
303	        </button>
304	      </form>
305	
306	      <table data-testid="invoice-payments-table">
307	        <tbody>
308	          {payments.map((p) => (
309	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
310	              <td data-testid="payment-amount">{money(p.amount)}</td>
311	              <td data-testid="payment-date">{p.date}</td>
312	            </tr>
313	          ))}
314	        </tbody>
315	      </table>
316	
317	      <form data-testid="payment-form" onSubmit={submitPayment}>
318	        <input
319	          data-testid="payment-form-amount"
320	          placeholder="Amount paid"
321	          value={paymentAmount}
322	          onChange={(e) => setPaymentAmount(e.target.value)}
323	        />
324	        <input
325	          data-testid="payment-form-date"
326	          type="date"
327	          value={paymentDate}
328	          onChange={(e) => setPaymentDate(e.target.value)}
329	        />
330	        <button data-testid="payment-form-submit" type="submit">
331	          Record payment
332	        </button>
333	      </form>
334	    </section>
335	  );
336	}
