338	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
339	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
340	// gives one obvious place to add a new lifecycle action.
341	function InvoiceActions({
342	  invoice,
343	  onOpen,
344	  onSend,
345	  onPay,
346	  onCancel,
347	}: {
348	  invoice: Invoice;
349	  onOpen: () => void;
350	  onSend: () => void;
351	  onPay: () => void;
352	  onCancel: () => void;
353	}) {
354	  return (
355	    <>
356	      <button data-testid={`invoice-open-${invoice.id}`} onClick={onOpen}>
357	        Open
358	      </button>
359	      {invoice.status === 'DRAFT' && (
360	        <button data-testid={`invoice-send-${invoice.id}`} onClick={onSend}>
361	          Send
362	        </button>
363	      )}
364	      {invoice.status === 'SENT' && (
365	        <button data-testid={`invoice-pay-${invoice.id}`} onClick={onPay}>
366	          Mark paid
367	        </button>
368	      )}
369	      {invoice.status === 'SENT' && (
370	        <button data-testid={`invoice-cancel-${invoice.id}`} onClick={onCancel}>
371	          Cancel
372	        </button>
373	      )}
374	    </>
375	  );
376	}
