378	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
379	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
380	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
381	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
382	function ProjectInvoices({
383	  projectId,
384	  onInvoicesChanged,
385	}: {
386	  projectId: number;
387	  onInvoicesChanged: () => void;
388	}) {
389	  const [invoices, setInvoices] = useState<Invoice[]>([]);
390	  const [amount, setAmount] = useState('');
391	  const [amountError, setAmountError] = useState('');
392	  const [sortByDue, setSortByDue] = useState(false);
393	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
394	
395	  async function load() {
396	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
397	    setInvoices(await res.json());
398	    onInvoicesChanged();
399	  }
400	
401	  useEffect(() => {
402	    void load();
403	  }, [projectId]);
404	
405	  async function submit(e: React.FormEvent) {
406	    e.preventDefault();
407	    const value = Number(amount);
408	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
409	      setAmountError('Amount must be more than zero');
410	      return;
411	    }
412	    setAmountError('');
413	    await fetch('/api/invoices', {
414	      method: 'POST',
415	      headers: { 'Content-Type': 'application/json' },
416	      body: JSON.stringify({ projectId, amount: value }),
417	    });
418	    setAmount('');
419	    await load();
420	  }
421	
422	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
423	  // routing them through one place means a new action is one more call site, not new plumbing.
424	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
425	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
426	    await load();
427	  }
428	
429	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
430	  const shownInvoices = sortByDue
431	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
432	    : invoices;
433	
434	  return (
435	    <>
436	      <form data-testid="invoice-form" onSubmit={submit}>
437	        <input
438	          data-testid="invoice-form-amount"
439	          placeholder="Amount"
440	          value={amount}
441	          onChange={(e) => setAmount(e.target.value)}
442	        />
443	        <button data-testid="invoice-form-submit" type="submit">
444	          Add invoice
445	        </button>
446	        {amountError && (
447	          <p data-testid="invoice-form-amount-error" role="alert">
448	            {amountError}
449	          </p>
450	        )}
451	      </form>
452	
453	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
454	        Sort by due date
455	      </button>
456	
457	      {openInvoiceId === null ? (
458	        <>
459	          <table data-testid="project-invoices-table">
460	            <tbody>
461	              {shownInvoices.map((inv) => (
462	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
463	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
464	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
465	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
466	                  <td data-testid="invoice-due">{inv.dueDate}</td>
467	                  <td data-testid="invoice-status">{inv.status}</td>
468	                  <td>
469	                    <InvoiceActions
470	                      invoice={inv}
471	                      onOpen={() => setOpenInvoiceId(inv.id)}
472	                      onSend={() => transition(inv.id, 'send')}
473	                      onPay={() => transition(inv.id, 'pay')}
474	                      onCancel={() => transition(inv.id, 'cancel')}
475	                    />
476	                  </td>
477	                </tr>
478	              ))}
479	            </tbody>
480	          </table>
481	
482	          <p data-testid="project-invoices-total">{money(total)}</p>
483	        </>
484	      ) : (
485	        <InvoiceDetail
486	          invoiceId={openInvoiceId}
487	          onChange={load}
488	          onClose={() => setOpenInvoiceId(null)}
489	        />
490	      )}
491	    </>
492	  );
493	}
