495	// A project's budget: what was set for it, what has been invoiced against it so far, and what is
496	// left over. Invoiced (and so remaining) is derived from the project's invoices, so the owner bumps
497	// `reloadKey` whenever they change and this re-reads the budget picture. Owns its own budget state.
498	function BudgetPanel({ projectId, reloadKey }: { projectId: number; reloadKey: number }) {
499	  const [budget, setBudget] = useState<ProjectBudget | null>(null);
500	  const [budgetInput, setBudgetInput] = useState('');
501	
502	  async function load() {
503	    const res = await fetch(`/api/projects/${projectId}/budget`);
504	    setBudget(await res.json());
505	  }
506	
507	  useEffect(() => {
508	    void load();
509	  }, [projectId, reloadKey]);
510	
511	  async function submit(e: React.FormEvent) {
512	    e.preventDefault();
513	    const value = Number(budgetInput);
514	    if (budgetInput.trim() === '' || !Number.isFinite(value) || value < 0) {
515	      return;
516	    }
517	    await fetch(`/api/projects/${projectId}/budget`, {
518	      method: 'POST',
519	      headers: { 'Content-Type': 'application/json' },
520	      body: JSON.stringify({ budget: value }),
521	    });
522	    setBudgetInput('');
523	    await load();
524	  }
525	
526	  return (
527	    <section data-testid="project-budget-panel">
528	      <p data-testid="project-budget">
529	        {budget && budget.budget != null ? moneyGrouped(budget.budget) : ''}
530	      </p>
531	      <p data-testid="project-invoiced">{moneyGrouped(budget ? budget.invoiced : 0)}</p>
532	      <p data-testid="project-remaining">
533	        {budget && budget.remaining != null ? moneyGrouped(budget.remaining) : ''}
534	      </p>
535	      <form data-testid="project-budget-form" onSubmit={submit}>
536	        <input
537	          data-testid="project-budget-input"
538	          placeholder="Budget"
539	          value={budgetInput}
540	          onChange={(e) => setBudgetInput(e.target.value)}
541	        />
542	        <button data-testid="project-budget-submit" type="submit">
543	          Set budget
544	        </button>
545	      </form>
546	    </section>
547	  );
548	}
