550	// A project's labels: the ones on it now (each removable) and a picker of the remaining labels to add
551	// another. Owns its own tag state, scoped to the one project.
552	function TagsPanel({ projectId }: { projectId: number }) {
553	  const [tags, reloadTags] = useJsonResource<Tag[]>(`/api/projects/${projectId}/tags`, []);
554	  const [allTags, reloadAllTags] = useJsonResource<Tag[]>('/api/tags', []);
555	  const [tagToAdd, setTagToAdd] = useState('');
556	
557	  async function reload() {
558	    await Promise.all([reloadTags(), reloadAllTags()]);
559	  }
560	
561	  async function addTag(e: React.FormEvent) {
562	    e.preventDefault();
563	    if (!tagToAdd) {
564	      return;
565	    }
566	    await fetch(`/api/projects/${projectId}/tags`, {
567	      method: 'POST',
568	      headers: { 'Content-Type': 'application/json' },
569	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
570	    });
571	    setTagToAdd('');
572	    await reload();
573	  }
574	
575	  async function removeTag(id: number) {
576	    await fetch(`/api/projects/${projectId}/tags/${id}/remove`, { method: 'POST' });
