586	            <button
587	              data-testid={`project-tag-remove-${tag.id}`}
588	              type="button"
589	              onClick={() => removeTag(tag.id)}
590	            >
591	              Remove
592	            </button>
593	          </span>
594	        ))}
595	      </div>
596	
597	      <form data-testid="project-tag-form" onSubmit={addTag}>
598	        <select
599	          data-testid="project-tag-add"
600	          value={tagToAdd}
601	          onChange={(e) => setTagToAdd(e.target.value)}
602	        >
603	          <option value="">Add a label</option>
604	          {allTags
605	            .filter((t) => !tags.some((mine) => mine.id === t.id))
606	            .map((t) => (
607	              <option key={t.id} value={String(t.id)}>
608	                {t.name}
609	              </option>
610	            ))}
611	        </select>
612	        <button data-testid="project-tag-add-submit" type="submit">
613	          Add label
614	        </button>
615	      </form>
616	    </>
617	  );
618	}
