620	// A project's tasks, filterable by whether they are still open or already done, each with a control
621	// to tick it off or reopen it. Owns its own task state, scoped to the one project.
622	function TasksPanel({ projectId }: { projectId: number }) {
623	  const [tasks, reload] = useJsonResource<Task[]>(`/api/tasks?projectId=${projectId}`, []);
624	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
625	
626	  async function toggleTask(id: number) {
627	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
628	    await reload();
629	  }
630	
631	  const shownTasks = tasks.filter((t) =>
632	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
633	  );
634	
635	  return (
636	    <>
637	      <select
638	        data-testid="task-filter"
639	        value={taskFilter}
