780	  const [clients] = useJsonResource<Client[]>('/api/clients', []);
781	  const [tags] = useJsonResource<Tag[]>('/api/tags', []);
782	  const [tagLinks] = useJsonResource<ProjectTagLink[]>('/api/project-tags', []);
783	  const [tagFilter, setTagFilter] = useState('');
784	  const [statusFilter, setStatusFilter] = useState('');
785	  const [name, setName] = useState('');
786	  const [code, setCode] = useState('');
787	  const [codeError, setCodeError] = useState('');
788	  const [clientId, setClientId] = useState('');
789	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
790	  const [openId, setOpenId] = useState<number | null>(null);
791	  // Archived projects are tucked away (retained, not deleted) and hidden by default; this toggle
792	  // reveals them again.
793	  const [showArchived, setShowArchived] = useState(false);
794	
795	  async function submit(e: React.FormEvent) {
796	    e.preventDefault();
797	    setCodeError('');
798	    if (!name.trim() || !clientId || !code.trim()) {
799	      return;
800	    }
801	    const res = await fetch('/api/projects', {
802	      method: 'POST',
803	      headers: { 'Content-Type': 'application/json' },
804	      body: JSON.stringify({ name, code, clientId: Number(clientId), status }),
805	    });
806	    // A code must be unique across jobs; the server rejects a duplicate, which surfaces here as a
807	    // field error rather than a new row.
808	    if (!res.ok) {
809	      setCodeError('That code is already in use');
810	      return;
811	    }
812	    setName('');
813	    setCode('');
814	    setClientId('');
815	    setStatus('ACTIVE');
816	    await reloadProjects();
817	  }
818	
819	  // Delete and archive are the same shape — POST the action, drop the open detail if it was showing
820	  // this project, then refresh the list — so they share one call site.
821	  async function act(id: number, action: 'delete' | 'archive') {
822	    await fetch(`/api/projects/${id}/${action}`, { method: 'POST' });
823	    if (openId === id) {
824	      setOpenId(null);
825	    }
826	    await reloadProjects();
827	  }
828	
829	  // Narrow the list one step at a time: hide archived unless asked, keep only projects carrying the
830	  // chosen label, then keep only the chosen status. An empty filter leaves that step wide open.
831	  const filterTagId = tagFilter ? Number(tagFilter) : null;
832	  const visible = projects
833	    .filter((p) => showArchived || !p.archived)
834	    .filter(
835	      (p) =>
836	        filterTagId === null ||
837	        tagLinks.some((l) => l.projectId === p.id && l.tagId === filterTagId),
838	    )
839	    .filter((p) => !statusFilter || p.status === statusFilter);
840	  const open = projects.find((p) => p.id === openId) ?? null;
841	
842	  return (
843	    <section data-testid="projects">
844	      <form data-testid="project-form" onSubmit={submit}>
845	        <input
846	          data-testid="project-form-name"
847	          placeholder="Job name"
848	          value={name}
849	          onChange={(e) => setName(e.target.value)}
850	        />
