861	        >
862	          <option value="">Select a client</option>
863	          {clients.map((c) => (
864	            <option key={c.id} value={String(c.id)}>
865	              {c.name}
866	            </option>
867	          ))}
868	        </select>
869	        <select
870	          data-testid="project-form-status"
871	          value={status}
872	          onChange={(e) => setStatus(e.target.value as ProjectStatus)}
873	        >
874	          <option value="ACTIVE">Active</option>
875	          <option value="ON_HOLD">On hold</option>
876	          <option value="FINISHED">Finished</option>
877	        </select>
878	        <button data-testid="project-form-submit" type="submit">
879	          Add job
880	        </button>
881	        {codeError && (
882	          <p data-testid="project-form-code-error" role="alert">
883	            {codeError}
884	          </p>
885	        )}
886	      </form>
887	
888	      <button
889	        data-testid="projects-show-archived"
890	        type="button"
891	        onClick={() => setShowArchived((v) => !v)}
892	      >
893	        {showArchived ? 'Hide archived' : 'Show archived'}
894	      </button>
895	
896	      <select
897	        data-testid="project-tag-filter"
898	        value={tagFilter}
899	        onChange={(e) => setTagFilter(e.target.value)}
900	      >
901	        <option value="">All labels</option>
902	        {tags.map((t) => (
903	          <option key={t.id} value={String(t.id)}>
904	            {t.name}
905	          </option>
906	        ))}
907	      </select>
