909	      <select
910	        data-testid="project-status-filter"
911	        value={statusFilter}
912	        onChange={(e) => setStatusFilter(e.target.value)}
913	      >
914	        <option value="">All statuses</option>
915	        <option value="ACTIVE">Active</option>
916	        <option value="ON_HOLD">On hold</option>
917	        <option value="FINISHED">Finished</option>
918	      </select>
919	
